<?php include "auth.php"; include "../database.php"; if(isset($_GET['id'],$_GET['action'])){ $id=intval($_GET['id']);$action=$_GET['action']; if(in_array($action,['Verified','Rejected'])){$s=$conn->prepare("UPDATE service_provider SET verification_status=? WHERE provider_id=?");$s->bind_param("si",$action,$id);$s->execute();} header("Location: providers.php");exit;} $r=$conn->query("SELECT * FROM service_provider ORDER BY provider_id DESC"); ?>
<!DOCTYPE html><html><head><meta charset="UTF-8"><title>Providers</title><link rel="stylesheet" href="../style.css"></head><body><main class="container"><h1>Provider Verification</h1><a class="btn secondary" href="index.php">Dashboard</a><table><tr><th>Name</th><th>Type</th><th>Languages</th><th>Status</th><th>Action</th></tr><?php while($p=$r->fetch_assoc()):?><tr><td><?=htmlspecialchars($p['name'])?></td><td><?=htmlspecialchars($p['service_type'])?></td><td><?=htmlspecialchars($p['languages'])?></td><td><?=htmlspecialchars($p['verification_status'])?></td><td><?php if($p['verification_status']==='Pending'):?><a class="btn" href="?id=<?=$p['provider_id']?>&action=Verified">Verify</a> <a class="btn secondary" href="?id=<?=$p['provider_id']?>&action=Rejected">Reject</a><?php endif;?></td></tr><?php endwhile;?></table></main></body></html>